#!/usr/bin/env node

import fs from 'node:fs';
import path from 'node:path';

const reportDir = path.resolve('docs/guardian');
const reportPath = path.join(reportDir, 'ai-repair-plan.md');
const now = new Date().toISOString();

const sections = [
  '# EMS Guardian AI Repair Plan',
  '',
  `Generated: ${now}`,
  '',
  '## Purpose',
  '',
  'This file is generated by EMS Guardian when CI, deploy, performance, smoke, or security checks fail. It gives Codex or an AI repair agent a safe patch plan without allowing blind production edits.',
  '',
  '## Repair loop',
  '',
  '1. Pull the newest failing logs from Vercel, GitHub Actions, npm audit, Playwright, Sentry, and Supabase advisors.',
  '2. Classify the failure as build, type, lint, route, runtime, performance, dependency, database, auth, storage, or security.',
  '3. Identify the smallest file set required for a fix.',
  '4. Create a branch named guardian/repair-YYYYMMDD-HHMM.',
  '5. Apply the smallest safe patch.',
  '6. Run npm run lint, npm run typecheck, npm run build, route smoke tests, performance budget, and security audit.',
  '7. Open a pull request with logs, diagnosis, changed files, risk level, and verification proof.',
  '8. Auto-merge only if every required check passes and the change is low risk.',
  '',
  '## Safe auto-repair categories',
  '',
  '- TypeScript prop mismatch fixes',
  '- Missing import fixes',
  '- Dead import removal',
  '- Route smoke timeout threshold adjustments with proof',
  '- Documentation/status report updates',
  '- Non-breaking dependency patch/minor updates when audit confirms safety',
  '',
  '## Manual approval required',
  '',
  '- Database migrations',
  '- Auth/RLS changes',
  '- Stripe/payment changes',
  '- OpenAI cost/usage changes',
  '- Production rollback',
  '- Large UI architecture rewrites',
  '- Any destructive data operation',
  '',
  '## Current repair status',
  '',
  'No active repair has been generated in this run.',
  '',
];

fs.mkdirSync(reportDir, { recursive: true });
fs.writeFileSync(reportPath, sections.join('\n'));
console.log(`Wrote ${reportPath}`);
